contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _to, uint256 _value) public payable {
        require(_to != address(0));
        require(_to != address(this));

        uint256 fromBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 toBefore = c.balanceOf(_to); if (__ESBMC_reverted()) return;

        bool reverted;
        bool success;
        bool s = c.transfer(_to, _value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            success = false;
            reverted = true;
        } else {
            success = s;
            reverted = false;
        }

        uint256 fromAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 toAfter = c.balanceOf(_to); if (__ESBMC_reverted()) return;

        assert(
            (!reverted && success && fromBefore >= _value && fromAfter == fromBefore - _value && toAfter == toBefore + _value) ||
            (reverted && fromAfter == fromBefore && toAfter == toBefore)
        );
    }

    receive() external payable {}
}

